    var r = Range.init(0, 10);
    while (r.next()) |val| {
        std.debug.print(\

, .{});

    // Count by 3s
    var r2 = Range.initWithStep(0, 20, 3);
    while (r2.next()) |val| {
        std.debug.print(\

, .{});

    // Count down
    var r3 = Range.initWithStep(10, 0, -1);
    while (r3.next()) |val| {
        std.debug.print(\

